// ─────────────────────────────────────────────────────────────
//  EDIT ME. This is the only node you need to change.
// ─────────────────────────────────────────────────────────────
const CONFIG = {
  // Two narrow, complementary searches. Keep them genuinely different:
  // two phrasings of the same question return the same links and waste a call.
  queryOne: 'AI model release OR launch this week',
  queryTwo: 'AI agent OR RAG OR retrieval engineering tooling update',

  // Google's freshness window: qdr:d day, qdr:w week, qdr:m month.
  // This scopes the time range deterministically, so the model never has to
  // reason about what "this week" means.
  freshness: 'qdr:w',

  resultsPerSearch: 10,

  // One line describing who reads this. It lands in the system prompt, and is
  // what stops the output reading like a press release.
  audience: 'engineers who build production automation and retrieval systems',

  // Enforced in code after the model answers, not by asking it to count.
  titleMaxChars: 60,
  excerptMaxChars: 155,
};

return [{ json: CONFIG }];

// Flatten both searches into one compact, citable block.
// Doing this here — rather than letting a model decide what to look up — is
// what keeps the whole run at exactly one model call.
const pull = (nodeName) => {
  const r = $(nodeName).first().json || {};
  const rows = Array.isArray(r.organic_results) ? r.organic_results : [];
  return rows.slice(0, 8).map((x) => ({
    title: String(x.title || '').trim(),
    link: String(x.link || '').trim(),
    date: String(x.date || '').trim(),
    snippet: String(x.snippet || '').trim(),
  })).filter((x) => x.title && x.link);
};

// De-duplicate by URL: the two queries overlap on a big week, and the same link
// listed twice reads to the model as two separate corroborating sources.
const seen = {};
const all = [];
for (const item of [...pull('Search One'), ...pull('Search Two')]) {
  if (seen[item.link]) continue;
  seen[item.link] = 1;
  all.push(item);
}

const findings = all.map((x, i) =>
  `${i + 1}. ${x.title}\n   URL: ${x.link}${x.date ? `\n   Date: ${x.date}` : ''}\n   ${x.snippet}`
).join('\n\n');

return [{ json: { count: all.length, findings: findings || 'No results returned.' } }];

// Asking a model to count characters is asking the wrong tool. The prompt says
// keep them short; the limit is enforced here, where it is arithmetic.
// An overlong title is trimmed on a word boundary rather than shipping as a
// truncated search result.
const cfg = $('Config').first().json;
const raw = $input.first().json;

// The Basic LLM Chain returns the parsed object under `output` on current
// versions and a JSON string in `text` on older ones. Accept either, so an n8n
// upgrade does not silently break the draft.
let d = raw.output ?? raw.text ?? raw;
if (typeof d === 'string') d = JSON.parse(d);

const clip = (value, max) => {
  const t = String(value ?? '').replace(/\s+/g, ' ').trim();
  if (t.length <= max) return t;
  const cut = t.slice(0, max);
  const lastSpace = cut.lastIndexOf(' ');
  const trimmed = lastSpace > max * 0.6 ? cut.slice(0, lastSpace) : cut;
  return trimmed.replace(/[\s,;:.\-–—]+$/, '');
};

const body = String(d.body ?? '').trim();

// Nothing is drafted rather than drafting an empty post. An empty draft in the
// CMS looks like a publishing decision somebody made; a failed execution looks
// like what it is.
if (!body) {
  throw new Error('The model returned no body — no draft created.');
}

return [{
  json: {
    title: clip(d.title, cfg.titleMaxChars),
    excerpt: clip(d.excerpt, cfg.excerptMaxChars),
    body,
    tags: Array.isArray(d.tags)
      ? d.tags.map((t) => String(t).toLowerCase().trim()).filter(Boolean).slice(0, 5)
      : [],
  },
}];
